287	export async function runReplay(opts: ReplayOptions = {}): Promise<ReplayResult> {
288	  const runsDir = opts.runsDir ?? RUNS_DIR;
289	  const webDir = opts.webBundlesDir === undefined ? WEB_BUNDLES_DIR : opts.webBundlesDir;
290	  const cassetteDir = opts.cassetteDir ?? DEFAULT_CASSETTE_DIR;
291	  const found = discoverBundles(runsDir, webDir);
292	  const lines: string[] = [];
293	  const failures: string[] = [];
294	
295	  // Every loaded bundle's content hash is recomputed; a tampered one is a visible failure.
296	  for (const f of found) if (f.error) failures.push(`TAMPERED OR INVALID BUNDLE ${f.file}: ${f.error}`);
297	  const byId = new Map<string, Found & { bundle: RunBundle }>();
298	  for (const f of found) {
299	    if (!f.bundle) continue;
300	    const prev = byId.get(f.bundle.runId);
301	    if (prev && prev.bundle.contentHash !== f.bundle.contentHash) {
302	      failures.push(`CONFLICT: bundle ${f.bundle.runId} differs between ${prev.file} and ${f.file}`);
303	      continue;
304	    }
305	    if (!prev) byId.set(f.bundle.runId, f as Found & { bundle: RunBundle });
306	  }
307	  lines.push(`verified ${byId.size} bundle(s) (content hash recomputed)${failures.length ? `; ${failures.length} failed verification` : ""}`);
